def note_pruefen(note):
    if note < 1 or note > 5:
        raise ValueError(f"Ungültige Note: {note}")
    return note

print(note_pruefen(2))
note_pruefen(7)   # ValueError: Ungültige Note: 7

def note_pruefen(note):
    if note < 1 or note > 5:
        raise ValueError(f"Ungültige Note: {note}")
    return note

for n in [3, 0]:
    try:
        note_pruefen(n)
        print(f"{n} ist ok")
    except ValueError as fehler:
        print(fehler)

class GuthabenError(Exception):
    pass

def abheben(guthaben, betrag):
    if betrag > guthaben:
        raise GuthabenError(f"Nur {guthaben} € verfügbar")
    return guthaben - betrag

try:
    rest = abheben(20, 50)
except GuthabenError as fehler:
    print(f"Abgelehnt: {fehler}")

class SpielError(Exception):
    pass

class UngueltigerZugError(SpielError):
    pass

class SpielVorbeiError(SpielError):
    pass

try:
    raise SpielVorbeiError("Keine Leben mehr")
except SpielError as fehler:
    print(f"Spielfehler: {fehler}")

try:
