def check(x):
    if x < 0:
        raise ValueError("Zu klein")
    return x

try:
    print(check(-1))
except ValueError as e:
    print(e)

class LeerError(Exception):
    pass

try:
    raise ValueError("A")
except LeerError:
    print("B")

class BasisError(Exception):
    pass

class KindError(BasisError):
    pass

try:
    raise KindError("weg")
except BasisError as e:
    print(f"Basis: {e}")
